		&XMLWhenReportLoading;
		&XMLWhenReportClosing;








// ===== GIỮ NGUYÊN CÁI CŨ =====
function on$GridReport$Render(sender, eventArgs) {
		var g = eventArgs.grid;  
		if (g._hiddenFields) {    
				var a = g._hiddenFields, h = '';
				for (var i = 0; i < a.length; i++) {
						setGridHiddenFields(g, a[i].Fields, a[i].Value);
						if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
				}
				g._externalHiddenFields = h;
		}
}

// ===== THÊM MỚI CHO HÌNH ẢNH =====
function on$GridReport$RenderImg(sender, eventArgs) {
		var g = eventArgs.grid;
		var colItem = g._getColumnOrder('ma_vt');      
		var colImg  = g._getColumnOrder('file_data');  // field ảnh trong grid
		refreshGridFileView(g, colItem, colImg);
}

// ===== HOOK VÀO LÚC LOAD =====
function load$GridReport$(g) {
		g.add_onRender(on$GridReport$Render);    // cái cũ
	//	g.add_onRender(on$GridReport$RenderImg); // cái mới (hình ảnh)
}

function dispose$GridReport$(g) {
		try { 
				g.remove_onRender(on$GridReport$Render);    
				//g.remove_onRender(on$GridReport$RenderImg); 
		} catch (ex) {}
}

// ===== fancybox =====
function checkfancybox() {
		if ($('[data-fancybox="gallery"]').length) {
				clearInterval(interval);
				$('[data-fancybox="gallery"]').fancybox({
						thumbs: { autoStart: true, axis: "10px" },
						buttons: ["zoom","slideShow","fullScreen","download","thumbs","close"]
				});
		}
}
var interval = setInterval(checkfancybox, 500);

// ===== render ảnh vào grid =====
function refreshGridFileView(g, colItem, colImg){
		for (var i = 1; i <= g._rowCount; i++) {
				var o2 = g._getItem(i, colImg);
				var file_enc = $func.trim(g._getItemValue(i, g._getColumnOrder('list_img')));
				if (o2 != null && file_enc != null && file_enc != '') {
						var Item = $func.trim(g._getItemValue(i, colItem));
						var imgPath = g._baseUrl + '/AppHandler/FileLib.ashx?action=view&id=' + Fox.base64encode(file_enc);

						var a = $get('link-image_' + i),
								z_img = $get('my-image_' + i);
						if (a != null) {
								a.href = imgPath;
								z_img.src = imgPath;
						} else {
								var elmlink = document.createElement("a");
								elmlink.setAttribute("data-fancybox", "gallery");
								elmlink.setAttribute("id", "link-image_" + i);
								elmlink.href = imgPath;

								var img = document.createElement("img");
								img.setAttribute("src", imgPath);
								img.setAttribute("id", "my-image_" + i);
								img.style.width = "80%";
								img.style.height = "18px";
								img.style.display = "block";
								img.style.margin = "auto";

								elmlink.appendChild(img);
								var po2  = o2.parentNode;
								po2.insertBefore(elmlink, o2);
						}
				}
		}
}

function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		var l = g._getColumnOrder($func.trim(a[i]));
		if (l != -1) g._setColumnVisible(l, !v);
	}
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
function beforeDrillDownWithCondition(g) {g._args.cancelEvent = !(g._getItemValue(g._activeRow, g._getColumnOrder('systotal')) == 1);}




